import unittest
from candidate import make_palindrome


class TestMakePalindrome(unittest.TestCase):
    def test_empty_string_returns_empty(self):
        self.assertEqual(make_palindrome(''), '')

    def test_single_character_returns_same(self):
        self.assertEqual(make_palindrome('a'), 'a')

    def test_single_character_b(self):
        self.assertEqual(make_palindrome('b'), 'b')

    def test_two_same_characters(self):
        self.assertEqual(make_palindrome('aa'), 'aa')

    def test_two_different_characters(self):
        self.assertEqual(make_palindrome('ab'), 'aba')

    def test_cat_expected_catac(self):
        self.assertEqual(make_palindrome('cat'), 'catac')

    def test_cata_expected_catac(self):
        self.assertEqual(make_palindrome('cata'), 'catac')

    def test_abc_expected_abcba(self):
        self.assertEqual(make_palindrome('abc'), 'abcba')

    def test_aba_already_palindrome(self):
        self.assertEqual(make_palindrome('aba'), 'aba')

    def test_racecar_already_palindrome(self):
        self.assertEqual(make_palindrome('racecar'), 'racecar')

    def test_all_same_chars(self):
        self.assertEqual(make_palindrome('aaaa'), 'aaaa')

    def test_three_chars_no_palindromic_suffix_longer_than_one(self):
        self.assertEqual(make_palindrome('abc'), 'abcba')

    def test_result_is_palindrome_for_cat(self):
        result = make_palindrome('cat')
        self.assertEqual(result, result[::-1])

    def test_result_is_palindrome_for_abc(self):
        result = make_palindrome('abc')
        self.assertEqual(result, result[::-1])

    def test_result_is_palindrome_for_cata(self):
        result = make_palindrome('cata')
        self.assertEqual(result, result[::-1])

    def test_result_starts_with_original_cat(self):
        result = make_palindrome('cat')
        self.assertTrue(result.startswith('cat'))

    def test_result_starts_with_original_abc(self):
        result = make_palindrome('abc')
        self.assertTrue(result.startswith('abc'))

    def test_result_starts_with_original_cata(self):
        result = make_palindrome('cata')
        self.assertTrue(result.startswith('cata'))

    def test_result_is_shortest_palindrome_for_cat(self):
        self.assertEqual(make_palindrome('cat'), 'catac')

    def test_result_is_shortest_palindrome_for_cata(self):
        self.assertEqual(make_palindrome('cata'), 'catac')

    def test_return_type_is_string(self):
        result = make_palindrome('cat')
        self.assertIsInstance(result, str)

    def test_return_type_for_empty(self):
        result = make_palindrome('')
        self.assertIsInstance(result, str)

    def test_none_input_raises_exception(self):
        with self.assertRaises((TypeError, AttributeError)):
            make_palindrome(None)

    def test_integer_input_raises_exception(self):
        with self.assertRaises((TypeError, AttributeError)):
            make_palindrome(123)

    def test_list_input_raises_exception(self):
        with self.assertRaises((TypeError, AttributeError)):
            make_palindrome(['a', 'b', 'c'])

    def test_long_string_result_is_palindrome(self):
        s = 'abcdefgh'
        result = make_palindrome(s)
        self.assertEqual(result, result[::-1])
        self.assertTrue(result.startswith(s))

    def test_result_length_minimum(self):
        self.assertEqual(len(make_palindrome('cat')), 5)
        self.assertEqual(len(make_palindrome('cata')), 5)

    def test_already_palindrome_no_change(self):
        s = 'abba'
        self.assertEqual(make_palindrome(s), s)

    def test_single_char_palindrome(self):
        s = 'z'
        self.assertEqual(make_palindrome(s), s)

    def test_two_char_palindrome(self):
        s = 'ab'
        result = make_palindrome(s)
        self.assertEqual(result, result[::-1])
        self.assertTrue(result.startswith(s))

    def test_unicode_characters(self):
        s = 'café'
        result = make_palindrome(s)
        self.assertEqual(result, result[::-1])
        self.assertTrue(result.startswith(s))

    def test_mixed_case_preserved(self):
        result = make_palindrome('Abc')
        self.assertEqual(result, result[::-1])
        self.assertTrue(result.startswith('Abc'))


if __name__ == '__main__':
    unittest.main()
